//! The module registry: modules sorted by `ORDER`, with duplicate detection.

use crate::{CpCtx, CpError};

/// One module's registration, as generated by `build.rs`.
#[derive(Clone, Copy)]
pub struct Registration {
    /// The module (file stem).
    pub name: &'static str,
    /// Registration order: lower registers first.
    pub order: u32,
    /// Registers the module's routes, tasks and checks.
    pub register: fn(&mut CpCtx) -> Result<(), CpError>,
}

/// Why a registry is unusable.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
pub enum RegistryError {
    /// Two modules share a name.
    #[error("module {0} is registered twice")]
    DuplicateName(&'static str),
    /// Two modules share an `ORDER`.
    #[error("modules {0} and {1} declare the same ORDER")]
    DuplicateOrder(&'static str, &'static str),
}

/// The sorted, checked set of modules.
#[derive(Clone)]
pub struct ModuleRegistry {
    modules: Vec<Registration>,
}

impl ModuleRegistry {
    /// Sorts by `(order, name)` and refuses duplicates.
    ///
    /// # Errors
    /// [`RegistryError`].
    pub fn new(registrations: &[Registration]) -> Result<Self, RegistryError> {
        let mut modules = registrations.to_vec();
        modules.sort_by(|a, b| (a.order, a.name).cmp(&(b.order, b.name)));
        for (index, module) in modules.iter().enumerate() {
            for other in modules.iter().skip(index + 1) {
                if module.name == other.name {
                    return Err(RegistryError::DuplicateName(module.name));
                }
                if module.order == other.order {
                    return Err(RegistryError::DuplicateOrder(module.name, other.name));
                }
            }
        }
        Ok(Self { modules })
    }

    /// The module names in registration order.
    #[must_use]
    pub fn names(&self) -> Vec<&'static str> {
        self.modules.iter().map(|m| m.name).collect()
    }

    /// Registers every module, in order; the first failure stops the start.
    ///
    /// # Errors
    /// The failing module's error.
    pub fn register_all(&self, ctx: &mut CpCtx) -> Result<(), CpError> {
        for module in &self.modules {
            ctx.current_module = module.name;
            (module.register)(ctx)?;
        }
        ctx.current_module = "";
        Ok(())
    }
}
